	BOARD_TITLE   =  #{BOARD_TITLE},
	BOARD_CONTENT =  #{BOARD_CONTENT}
WHERE OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND BOARD_DIV = #{BOARD_DIV} AND BOARD_NO = #{BOARD_NO}

