UPDATE A SET A.JOIN_DATE = B.JOIN_DATE, A.DEPT_CD = B.DEPT_CD, A.JOB_DUTY_CD = B.JOB_DUTY_CD, A.NAME = B.NAME, A.HP_NO = B.HP_NO, A.REMARKS = B.REMARKS FROM dbo.TAD_TMP_EMP A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_GBN} AS EMP_GBN, #{row.EMP_NO} AS EMP_NO, #{row.JOIN_DATE} AS JOIN_DATE, #{row.DEPT_CD} AS DEPT_CD, #{row.JOB_DUTY_CD} AS JOB_DUTY_CD, #{row.NAME} AS NAME, #{row.HP_NO} AS HP_NO, #{row.REMARKS} AS REMARKS
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.EMP_GBN = B.EMP_GBN

UPDATE A SET A.RESIGN_DATE = B.RESIGN_DATE, A.RESIGN_REASON = B.RESIGN_REASON FROM dbo.TAD_TMP_EMP A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_GBN} AS EMP_GBN, #{row.EMP_NO} AS EMP_NO, #{row.RESIGN_DATE} AS RESIGN_DATE, #{row.RESIGN_REASON} AS RESIGN_REASON
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.EMP_GBN = B.EMP_GBN

UPDATE A SET A.RESIGN_DATE = NULL, A.RESIGN_REASON = NULL FROM dbo.TAD_TMP_EMP A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_GBN} AS EMP_GBN, #{row.EMP_NO} AS EMP_NO
) AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.EMP_GBN = B.EMP_GBN

mapper.select:
SELECT A.OFFICE_CODE, A.EMP_NO, A.EMP_GBN, A.REG_SEQ, A.REG_DATE, A.ABSENT_CD, E.ABSENT_NAME, A.START_DATE, A.END_DATE, A.USE_DAY_CNT, A.DESCR, A.IDX, B.NAME, B.DEPT_CD, B.JOB_DUTY_CD, C.DEPT_NAME, D.JOB_DUTY_NAME, CASE WHEN (NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NOT NULL AND B.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112) THEN '퇴사' WHEN (NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NULL OR B.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND B.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112) THEN '재직' ELSE ' ' END AS JOIN_YN FROM dbo.TAD_TMP_ABSENT AS A LEFT JOIN dbo.TAD_TMP_EMP AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.EMP_GBN = B.EMP_GBN LEFT JOIN dbo.THR_DEPT AS C ON B.DEPT_CD = C.DEPT_CD AND C.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} LEFT JOIN dbo.THR_JOB_DUTY AS D ON B.JOB_DUTY_CD = D.JOB_DUTY_CD AND D.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} LEFT JOIN dbo.TAD_TMP_ABSENT_ITEM AS E ON A.ABSENT_CD = E.ABSENT_CD AND E.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.EMP_GBN = #{EMP_GBN}
AND A.START_DATE >= #{START_DATE} AND A.END_DATE <= #{END_DATE}
AND A.START_DATE >= #{START_DATE}
AND A.END_DATE <= #{END_DATE}
AND (NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NULL OR B.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND B.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112)
AND NULLIF(LTRIM(RTRIM(B.RESIGN_DATE)), '') IS NOT NULL AND B.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112)
AND B.EMP_NO = #{EMP_NO}
ORDER BY A.START_DATE DESC, A.END_DATE DESC

update.if:
UPDATE A SET A.REG_DATE = B.REG_DATE, A.ABSENT_CD = B.ABSENT_CD, A.START_DATE = B.START_DATE, A.END_DATE = B.END_DATE, A.USE_DAY_CNT = B.USE_DAY_CNT, A.DESCR = B.DESCR, A.IDX = B.IDX FROM dbo.TAD_TMP_ABSENT A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_GBN} AS EMP_GBN, #{row.EMP_NO} AS EMP_NO, #{row.REG_SEQ} AS REG_SEQ, #{row.REG_DATE} AS REG_DATE, #{row.ABSENT_CD} AS ABSENT_CD, #{row.START_DATE} AS START_DATE, #{row.END_DATE} AS END_DATE, #{row.USE_DAY_CNT} AS USE_DAY_CNT, #{row.DESCR} AS DESCR, #{row.IDX} AS IDX
) B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.REG_SEQ = B.REG_SEQ AND A.EMP_GBN = B.EMP_GBN

