DELETE FROM dbo.TAD_TMP_ABSENT WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO, #{row.REG_SEQ} AS REG_SEQ, #{EMP_GBN} AS EMP_GBN
) AS temp WHERE temp.OFFICE_CODE = TAD_TMP_ABSENT.OFFICE_CODE AND temp.EMP_NO = TAD_TMP_ABSENT.EMP_NO AND temp.REG_SEQ = TAD_TMP_ABSENT.REG_SEQ AND temp.EMP_GBN = TAD_TMP_ABSENT.EMP_GBN )

mapper.select:
SELECT A.OFFICE_CODE, A.EMP_NO, A.EMP_GBN, A.NAME, A.DEPT_CD, A.JOB_DUTY_CD, CASE WHEN NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NOT NULL AND A.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112) THEN '퇴사' WHEN (NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NULL OR A.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND A.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112) THEN '재직' ELSE '' END AS STATUS, SUBSTRING(B.START_DATE, 1, 6) AS DATE, B.ABSENT_CD, SUM(B.USE_DAY_CNT) AS USE_DAY_CNT, C.DEPT_NAME, D.JOB_DUTY_NAME FROM dbo.TAD_TMP_EMP AS A LEFT JOIN dbo.TAD_TMP_ABSENT AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EMP_NO = B.EMP_NO AND A.EMP_GBN = B.EMP_GBN AND (SUBSTRING(B.START_DATE, 1, 6) = #{DATE} OR B.START_DATE IS NULL) LEFT JOIN dbo.THR_DEPT AS C ON A.DEPT_CD = C.DEPT_CD AND C.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} LEFT JOIN dbo.THR_JOB_DUTY AS D ON A.JOB_DUTY_CD = D.JOB_DUTY_CD AND D.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.EMP_GBN = #{EMP_GBN}
AND A.NAME LIKE '%' + #{NAME} + '%'
AND ((NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NULL OR SUBSTRING(A.RESIGN_DATE, 1, 6) >= SUBSTRING(B.START_DATE, 1, 6)) AND SUBSTRING(A.JOIN_DATE, 1, 6) <= SUBSTRING(B.START_DATE, 1, 6)) GROUP BY A.OFFICE_CODE, A.EMP_NO, A.EMP_GBN, A.NAME, A.DEPT_CD, A.JOB_DUTY_CD, CASE WHEN (NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NOT NULL AND A.RESIGN_DATE < CONVERT(VARCHAR(8), GETDATE(), 112) THEN '퇴사' WHEN ((NULLIF(LTRIM(RTRIM(A.RESIGN_DATE)), '') IS NULL OR A.RESIGN_DATE >= CONVERT(VARCHAR(8), GETDATE(), 112)) AND A.JOIN_DATE <= CONVERT(VARCHAR(8), GETDATE(), 112) THEN '재직' ELSE '' END, SUBSTRING(B.START_DATE, 1, 6), B.ABSENT_CD, C.DEPT_NAME, D.JOB_DUTY_NAME ORDER BY CONVERT(INT, A.EMP_NO);

SELECT A.OFFICE_CODE, A.EQU_GBN, A.EQU_NO, A.REPAIR_SEQ, B.EQU_NAME, B.INSTALL_DATE, B.INSTALL_PLACE, A.ST_DATE, A.END_DATE, A.TRO_USER, A.TRO_AMT, A.EQU_USER, A.CONTENT FROM dbo.TEN_TROUBLE AS A LEFT JOIN dbo.TEN_EQUIPMENT AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EQU_GBN = B.EQU_GBN AND A.EQU_NO = b.EQU_NO WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.EQU_GBN = '112001' AND ISNULL(B.DISUSE_GBN, 'Y') != 'N'
AND A.ST_DATE >= #{ST_DATE} AND A.END_DATE <= #{END_DATE}
AND A.ST_DATE >= #{ST_DATE}
AND A.END_DATE <= #{END_DATE}
AND A.NAME LIKE '%' + #{NAME} + '%'
ORDER BY CONVERT(INT, A.ST_DATE), CONVERT(INT, A.END_DATE);

SELECT A.OFFICE_CODE, A.EQU_GBN, A.EQU_NO, A.EQU_NAME, A.FORM, A.DIMENSION, A.SIZE, A.INSTALL_DATE, A.INSTALL_PLACE, A.DISUSE_DATE, A.DISUSE_REASON FROM dbo.TEN_EQUIPMENT AS A WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.EQU_GBN = '112001' AND ISNULL(A.DISUSE_GBN, 'Y') = 'N'
AND A.INSTALL_DATE >= #{ST_DATE}
AND A.INSTALL_DATE <= #{END_DATE}
ORDER BY CONVERT(INT, A.INSTALL_DATE), CONVERT(INT, A.EQU_NO);

update.if:
UPDATE A SET A.DISUSE_GBN = 'Y', A.DISUSE_DATE = NULL, A.DISUSE_REASON = NULL FROM dbo.TEN_EQUIPMENT A JOIN (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EQU_GBN} AS EQU_GBN, #{row.EQU_NO} AS EQU_NO
) B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.EQU_GBN = B.EQU_GBN AND A.EQU_NO = B.EQU_NO
